"""A small, independent Task-compatible runner."""
import os, sys, json
from pathlib import Path
import yamlmini
import execution
VERSION='3.51.1'
HELP='''Usage: task [flags...] [task...]\nRuns the specified task(s). Falls back to the "default" task if no task name was specified, or lists all tasks if an unknown task name was specified.\n\nOptions:\n  -h, --help       Shows Task usage.\n  --version        Shows Task version.\n  -l, --list       Lists tasks with description.\n  -a, --list-all   Lists all tasks.\n  -t, --taskfile   Choose Taskfile.\n  -d, --dir        Sets execution directory.\n  -n, --dry        Prints tasks without executing.\n  -s, --silent     Disables command echoing.\n  -v, --verbose    Enables verbose mode.\n  -f, --force      Forces execution.\n  -x, --exit-code  Passes through task command exit status.\n'''

def find_file(root, name=None):
    if name:
        p=Path(name); p=p if p.is_absolute() else Path(root)/p
        return p
    for n in ('Taskfile.yml','Taskfile.yaml','taskfile.yml','taskfile.yaml'):
        p=Path(root)/n
        if p.exists(): return p
    return None

def list_tasks(data, all_tasks=False, silent=False, sort='default'):
    tasks=data.get('tasks') or {}
    rows=[]
    for name,t in tasks.items():
        if isinstance(t,dict) and t.get('internal'): continue
        desc=t.get('desc','') if isinstance(t,dict) else ''
        if not all_tasks and not desc: continue
        rows.append((name,str(desc or '').splitlines()[0]))
    if sort=='alphanumeric': rows.sort(key=lambda x:x[0].lower())
    if silent:
        for n,_ in rows: print(n)
    elif not rows:
        print('task: No tasks with description available. Try --list-all to list all tasks',file=sys.stderr)
    else:
        width=max(len(n) for n,_ in rows)
        for n,d in rows: print(f'* {n.ljust(width)}: {d}')

def main(argv):
    args=list(argv); root=os.getcwd(); taskfile=None; dry=silent=verbose=force=exit_code=False; listmode=None; sort='default'; cli_args=[]; names=[]
    if '--' in args:
        k=args.index('--'); cli_args=args[k+1:]; args=args[:k]
    i=0
    while i<len(args):
        a=args[i]
        if a in ('-h','--help'): print(HELP,end=''); return 0
        if a=='--version': print('Task version: v'+VERSION); return 0
        if a in ('-i','--init'):
            p=Path(root)/'Taskfile.yml'
            if p.exists(): print(f'task: {p} already exists',file=sys.stderr); return 201
            p.write_text("version: '3'\n\ntasks:\n  default:\n    cmds:\n      - echo 'Hello, World!'\n")
            print('Taskfile.yml created'); return 0
        if a in ('-l','--list'): listmode='list'
        elif a in ('-a','--list-all'): listmode='all'
        elif a in ('-n','--dry'): dry=True
        elif a in ('-s','--silent'): silent=True
        elif a in ('-v','--verbose'): verbose=True
        elif a in ('-f','--force'): force=True
        elif a in ('-x','--exit-code'): exit_code=True
        elif a=='--json': listmode='json'
        elif a=='--disable-fuzzy': pass
        elif a in ('-d','--dir','-t','--taskfile','-C','--concurrency','-o','--output','-I','--interval','--sort'):
            if i+1<len(args):
                i+=1; v=args[i]
                if a in ('-d','--dir'): root=os.path.abspath(v)
                elif a in ('-t','--taskfile'): taskfile=v
                elif a=='--sort': sort=v
        elif a.startswith('-'):
            # Accept nonessential boolean switches.
            pass
        else: names.append(a)
        i+=1
    fp=find_file(root,taskfile)
    if fp is None or not fp.exists():
        print('task: Cannot find Taskfile',file=sys.stderr); return 201
    try: data=yamlmini.loads(fp.read_text())
    except Exception as e:
        print(f'task: {e}',file=sys.stderr); return 201
    if not isinstance(data,dict): data={}
    if listmode:
        if listmode=='json':
            out=[]
            for n,t in (data.get('tasks') or {}).items():
                if isinstance(t,dict) and t.get('internal'): continue
                if isinstance(t,dict): out.append({'name':n,'task':n,'desc':t.get('desc',''),'location':{'taskfile':str(fp)}})
            print(json.dumps(out,ensure_ascii=False)); return 0
        list_tasks(data,listmode=='all',silent,sort); return 0
    if not names: names=['default'] if 'default' in (data.get('tasks') or {}) else []
    if not names:
        list_tasks(data,False,False,sort); return 0
    return execution.run_tasks(data,names,directory=root,dry=dry,silent=silent,verbose=verbose,force=force,cli_args=cli_args,exit_code=exit_code)

if __name__=='__main__': sys.exit(main(sys.argv[1:]))
