"""Task configuration and TASK_* environment precedence helpers."""
from __future__ import annotations

import os
from pathlib import Path

from yamlmini import loads


_ENV_OPTIONS = {
    "TASK_VERBOSE": ("verbose", "bool"),
    "TASK_SILENT": ("silent", "bool"),
    "TASK_COLOR": ("color", "bool"),
    "TASK_DISABLE_FUZZY": ("disable-fuzzy", "bool"),
    "TASK_CONCURRENCY": ("concurrency", "int"),
    "TASK_FAILFAST": ("failfast", "bool"),
    "TASK_DRY": ("dry", "bool"),
    "TASK_ASSUME_YES": ("yes", "bool"),
    "TASK_INTERACTIVE": ("interactive", "bool"),
}


def _convert(value: str, kind: str):
    if kind == "bool":
        v = value.strip().lower()
        if v in ("true", "1", "yes", "on"):
            return True
        if v in ("false", "0", "no", "off"):
            return False
        return None
    if kind == "int":
        try:
            return int(value)
        except ValueError:
            return None
    return value


def _read_config(path: Path) -> dict:
    try:
        data = loads(path.read_text(encoding="utf-8"))
        return data if isinstance(data, dict) else {}
    except (OSError, UnicodeError, ValueError):
        return {}


def load_config(start_dir=None, env=None) -> dict:
    """Load config files from low to high priority, then TASK_* overrides.

    ``start_dir`` is the effective project/taskfile directory. Values from a
    later file replace values from earlier files. Unknown keys are preserved.
    """
    environ = os.environ if env is None else env
    here = Path(start_dir or os.getcwd()).expanduser().resolve()
    if here.is_file():
        here = here.parent
    home = Path(environ.get("HOME", str(Path.home()))).expanduser().resolve()

    paths = []
    xdg = environ.get("XDG_CONFIG_HOME")
    if xdg:
        xdg_dir = Path(xdg).expanduser() / "task"
        paths.extend([xdg_dir / "taskrc.yml", xdg_dir / "taskrc.yaml"])

    # Ancestor configuration is merged from the outermost directory inward.
    dirs = []
    cur = here
    while cur != home and home in cur.parents:
        dirs.append(cur)
        cur = cur.parent
    # Configs outside HOME still get discovered up to the filesystem root.
    if not dirs and here != home:
        cur = here
        while cur != cur.parent:
            dirs.append(cur)
            cur = cur.parent
    for directory in [home, *reversed(dirs)]:
        paths.extend([directory / ".taskrc.yml", directory / ".taskrc.yaml"])

    result = {}
    for path in paths:
        if path.is_file():
            result.update(_read_config(path))

    for env_name, (key, kind) in _ENV_OPTIONS.items():
        if env_name in environ:
            parsed = _convert(str(environ[env_name]), kind)
            if parsed is not None:
                result[key] = parsed
    return result

