"""Task execution primitives shared by the CLI implementation."""
import os, re, shlex, subprocess, sys


def render(s, values):
    if not isinstance(s, str):
        return s
    # Task's common Go-template interpolation forms.
    def repl(m):
        key=m.group(1).strip()
        if key.startswith('.'): key=key[1:]
        if key.startswith('$'): key=key[1:]
        v=values.get(key, '')
        if isinstance(v, bool): return str(v).lower()
        if isinstance(v, (list,dict)): return str(v)
        return str(v)
    return re.sub(r'{{\s*([.$][\w.-]+)\s*}}', repl, s)


def run_tasks(taskfile, names, *, directory=None, dry=False, silent=False, verbose=False,
              force=False, cli_args=None, env=None, failfast=False, exit_code=False):
    """Run named tasks from a decoded Taskfile mapping; return process status."""
    tasks=taskfile.get('tasks') or {}
    base=os.path.abspath(directory or os.getcwd())
    global_vars=dict(taskfile.get('vars') or {})
    executed=set(); active=set(); failed=0
    def run(name, alias=None):
        nonlocal failed
        if name in active:
            print(f'task: task dependency cycle detected: {name}', file=sys.stderr); failed=1; return
        if name in executed: return
        t=tasks.get(name)
        if t is None:
            print(f'task: Task "{name}" does not exist', file=sys.stderr); failed=1; return
        if isinstance(t,str): t={'cmds':[t]}
        elif isinstance(t,list): t={'cmds':t}
        if not isinstance(t,dict): t={}
        active.add(name)
        for dep in reversed(t.get('deps',[]) or []):
            if failed: break
            if isinstance(dep,dict): run(dep.get('task',''))
            else: run(str(dep))
        if failed and failfast:
