"""Expansion of local Taskfile includes into the root task mapping."""
from pathlib import Path
from yamlmini import loads

NAMES=('Taskfile.yml','taskfile.yml','Taskfile.yaml','taskfile.yaml','Taskfile.dist.yml','taskfile.dist.yml','Taskfile.dist.yaml','taskfile.dist.yaml')

class IncludeError(Exception):
    pass

def expand(root, taskfile):
    root_path=Path(taskfile).resolve()
    tasks=root.setdefault('tasks',{})
    if not isinstance(tasks,dict): tasks={}; root['tasks']=tasks
    stack={root_path}
    def expand_one(data, base, prefix, include_spec, depth):
        if depth>20: raise IncludeError('maximum include depth exceeded')
        if isinstance(include_spec,str): spec={'taskfile':include_spec}
        elif isinstance(include_spec,dict): spec=include_spec
        else: spec={}
        source=spec.get('taskfile') or spec.get('dir')
        if not source: return
        candidate=Path(str(source))
        if not candidate.is_absolute(): candidate=base/candidate
        if candidate.is_dir():
            candidate=next((candidate/n for n in NAMES if (candidate/n).is_file()),candidate/'Taskfile.yml')
        candidate=candidate.resolve()
        if not candidate.is_file():
            if spec.get('optional'): return
            raise IncludeError(f'No Taskfile found at "{candidate}"')
        if candidate in stack: raise IncludeError(f'circular include detected for "{candidate}"')
        try: child=loads(candidate.read_text()) or {}
        except Exception as e: raise IncludeError(f'Failed to parse included Taskfile "{candidate}": {e}')
        if not isinstance(child,dict): raise IncludeError(f'Included Taskfile "{candidate}" must be a mapping')
        child_tasks=child.get('tasks') or {}
        if not isinstance(child_tasks,dict): return
        stack.add(candidate)
        for nested_name,nested_spec in (child.get('includes') or {}).items():
            expand_one(child,candidate.parent,prefix+(str(nested_name)+':' if not (isinstance(nested_spec,dict) and nested_spec.get('flatten')) else ''),nested_spec,depth+1)
        namespace_aliases=spec.get('aliases',[]) or []
        if isinstance(namespace_aliases,str): namespace_aliases=[namespace_aliases]
        prefix_parts=[x for x in prefix.rstrip(':').split(':') if x]
        parent_prefix=':'.join(prefix_parts[:-1])+(':' if len(prefix_parts)>1 else '')
        excluded=set(str(x) for x in (spec.get('excludes') or []))
        inherited={**(child.get('vars') or {}),**(spec.get('vars') or {})}
        working_dir=spec.get('dir') or str(candidate.parent)
        for child_name,raw_task in child_tasks.items():
            child_name=str(child_name)
            if child_name in excluded: continue
            task=dict(raw_task) if isinstance(raw_task,dict) else ({'cmds':[raw_task]} if isinstance(raw_task,str) else {'cmds':raw_task} if isinstance(raw_task,list) else {})
            task['vars']={**inherited,**(task.get('vars') or {})}
            task['env']={**(child.get('env') or {}),**(task.get('env') or {})}
            if child.get('silent'): task.setdefault('silent',True)
            if spec.get('internal'): task['internal']=True
            task.setdefault('dir',working_dir)
            child_aliases=task.get('aliases',[]) or []
            if isinstance(child_aliases,str): child_aliases=[child_aliases]
            names=[prefix+child_name]
            for qualified in names:
                aliases=[prefix+str(x) for x in child_aliases]
                for alias in namespace_aliases:
                    alias_prefix=parent_prefix+str(alias)+':'
                    aliases.append(alias_prefix+child_name)
                    aliases.extend(alias_prefix+str(x) for x in child_aliases)
                task['aliases']=list(dict.fromkeys(aliases))
                def qualify(value):
                    if value in child_tasks:
                        return prefix+str(value)
                    for local_name, local_task in child_tasks.items():
                        local_aliases=local_task.get('aliases',[]) if isinstance(local_task,dict) else []
                        if isinstance(local_aliases,str): local_aliases=[local_aliases]
                        if value in local_aliases: return prefix+str(local_name)
                    return value
                deps=task.get('deps') or []
                if isinstance(deps,(str,dict)): deps=[deps]
                rewritten=[]
                for dep in deps:
                    if isinstance(dep,dict) and 'task' in dep:
                        dep=dict(dep); dep['task']=qualify(dep['task']); rewritten.append(dep)
                    else: rewritten.append(qualify(dep))
                if 'deps' in task: task['deps']=rewritten
                cmds=task.get('cmds') or []
                if isinstance(cmds,(str,dict)): cmds=[cmds]
                new_cmds=[]
                for cmd in cmds:
                    if isinstance(cmd,dict) and 'task' in cmd:
                        cmd=dict(cmd); cmd['task']=qualify(cmd['task'])
                    new_cmds.append(cmd)
                if 'cmds' in task: task['cmds']=new_cmds
                tasks[qualified]=task.copy()
        stack.remove(candidate)
    includes=root.get('includes') or {}
    if isinstance(includes,dict):
        for prefix,spec in includes.items():
            namespaced=not (isinstance(spec,dict) and spec.get('flatten'))
            expand_one(root,root_path.parent,(str(prefix)+':' if namespaced else ''),spec,1)
    return root

